import test from "node:test";
import assert from "node:assert/strict";
import { LinkedList } from "./attempt.js";

const todo = LinkedList.prototype.pushBack.toString().includes("TODO");
const skip = todo && "unsolved — edit attempt.js (delete the TODO lines) to activate these tests";

test("pushBack appends to the end", { skip }, () => {
  const list = new LinkedList();
  list.pushBack(1);
  list.pushBack(2);
  list.pushBack(3);
  assert.deepEqual(list.toArray(), [1, 2, 3]);
  assert.equal(list.head.value, 1); // plain { value, next } nodes
  assert.equal(list.head.next.next.next, null); // null marks the end
});

test("pushFront prepends", { skip }, () => {
  const list = new LinkedList();
  list.pushFront(1);
  list.pushFront(2);
  list.pushFront(3);
  assert.deepEqual(list.toArray(), [3, 2, 1]);

  const mixed = new LinkedList();
  mixed.pushBack(1);
  mixed.pushBack(2);
  mixed.pushFront(0);
  assert.deepEqual(mixed.toArray(), [0, 1, 2]);
});

test("a new list is empty", { skip }, () => {
  const list = new LinkedList();
  assert.deepEqual(list.toArray(), []);
  assert.equal(list.head, null);
});

test("fromArray builds the list in order", { skip }, () => {
  assert.deepEqual(LinkedList.fromArray([10, 20, 30]).toArray(), [10, 20, 30]);
});

test("removeFirstMatch removes only the first occurrence", { skip }, () => {
  const list = LinkedList.fromArray([1, 2, 3, 2]);
  assert.equal(list.removeFirstMatch(2), true);
  assert.deepEqual(list.toArray(), [1, 3, 2]); // the second 2 stays
});

test("removing the head, then the tail, leaves a usable list", { skip }, () => {
  const list = LinkedList.fromArray([1, 2, 3]);
  list.removeFirstMatch(1); // the head
  assert.deepEqual(list.toArray(), [2, 3]);
  list.removeFirstMatch(3); // the last node
  list.pushBack(9); // still has to land at the end
  assert.deepEqual(list.toArray(), [2, 9]);
});

test("removing a value that isn't there returns false", { skip }, () => {
  const list = LinkedList.fromArray(["a", "b"]);
  assert.equal(list.removeFirstMatch("z"), false);
  assert.deepEqual(list.toArray(), ["a", "b"]); // unchanged
});

/**
 * Singly linked list — nodes and pointers, no arrays inside.
 *
 * A node is a plain object { value, next }, with next === null on the
 * last node. The list keeps two pointers:
 *   head — the first node (null when empty)
 *   tail — the last node  (null when empty), so pushBack is O(1)
 *
 * The tail pointer is a promise: every method that can change the last
 * node has to keep it true. There are exactly three such places, all
 * marked below.
 */
export class LinkedList {
  constructor() {
    /** @type {{ value: *, next: object|null }|null} */
    this.head = null;
    /** @type {{ value: *, next: object|null }|null} */
    this.tail = null;
  }

  /**
   * Add a value at the end of the list. O(1) thanks to `tail`.
   * @param {*} value
   * @returns {void}
   */
  pushBack(value) {
    const node = { value, next: null };
    if (this.head === null) {
      this.head = node; // empty list: the new node is both ends
      this.tail = node; // (tail promise #1)
    } else {
      this.tail.next = node; // link the old last node to it...
      this.tail = node; // ...and it becomes the last (tail promise #2)
    }
  }

  /**
   * Add a value at the front of the list. O(1).
   * @param {*} value
   * @returns {void}
   */
  pushFront(value) {
    // Works even on an empty list: next becomes null, which is correct.
    this.head = { value, next: this.head };
    if (this.tail === null) this.tail = this.head; // was empty (tail promise #1)
  }

  /**
   * Copy the values into a plain array, front to back. O(n).
   * @returns {*[]} [] for an empty list
   */
  toArray() {
    const values = [];
    // The walking loop — every method here is a variation of it.
    for (let node = this.head; node !== null; node = node.next) {
      values.push(node.value);
    }
    return values;
  }

  /**
   * Remove the first node whose value === the given value. O(n).
   * @param {*} value
   * @returns {boolean} true if a node was removed, false if not found
   */
  removeFirstMatch(value) {
    if (this.head === null) return false;

    // Case 1: the head matches — no previous node to re-link.
    if (this.head.value === value) {
      this.head = this.head.next;
      if (this.head === null) this.tail = null; // list is now empty (tail promise #3)
      return true;
    }

    // Case 2: walk with a `prev` pointer, because to unlink a node you
    // need the node BEFORE it — a singly linked node can't reach back.
    let prev = this.head;
    while (prev.next !== null) {
      if (prev.next.value === value) {
        if (prev.next === this.tail) this.tail = prev; // removed the last node (tail promise #3)
        prev.next = prev.next.next; // splice it out
        return true;
      }
      prev = prev.next;
    }
    return false; // walked off the end without a match
  }

  /**
   * Build a new list containing the array's values, in order. O(n).
   * @param {*[]} values
   * @returns {LinkedList}
   */
  static fromArray(values) {
    const list = new LinkedList();
    for (const value of values) list.pushBack(value); // O(1) each
    return list;
  }
}

